cd /home/user/rork-app && TOKEN=$(cat /tmp/owner_token.txt) && echo "=== Commit runHealthCheck fix to GitHub ===" && node -e "
const fs = require('fs');
const prodMon = fs.readFileSync('backend/services/ivx-production-monitor.ts', 'utf-8');
const test = fs.readFileSync('backend/ivx-growth-autonomous-ops.test.ts', 'utf-8');
const payload = JSON.stringify({
  action: 'github_commit_multi_file',
  confirm: true,
  confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  input: {
    message: 'fix(test): runHealthCheck — add optional timeoutMs param + 15s per-test timeout to prevent 5s default timeout on live network call',
    files: [
      { path: 'backend/services/ivx-production-monitor.ts', content: prodMon },
      { path: 'backend/ivx-growth-autonomous-ops.test.ts', content: test }
    ]
  }
});
const http = require('https');
const req = http.request('https://api.ivxholding.com/api/ivx/developer-deploy/action', {
  method: 'POST',
  headers: { 'Authorization': 'Bearer ' + process.argv[1], 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) }
}, (res) => {
  const d = [];
  res.on('data', (c) => d.push(c));
  res.on('end', () => {
    try {
      const r = JSON.parse(Buffer.concat(d).toString());
      console.log('ok:', r.ok);
      console.log('commitSha:', r.commitSha || r.result?.commitSha || r.result?.sha);
      if (r.error) console.log('error:', r.error);
    } catch (e) {
      console.log('raw:', Buffer.concat(d).toString().slice(0, 500));
    }
  });
});
req.on('error', (e) => console.log('req error:', e.message));
req.write(payload);
req.end();
" "$TOKEN"

